unsafe fn xmlParserPrintFileContextInternal(
    mut input: xmlParserInputPtr,
    mut channel: xmlGenericErrorFunc,
    mut data: *mut c_void,
) {
    let mut content: [xmlChar; 81] = [0; 81];

    if input.is_null() {
        return;
    }

    let input_ref = unsafe { &*input }; // SAFETY: `input` was checked non-null and is only read.
    let mut cur = input_ref.cur;
    if cur.is_null() {
        return;
    }
    let base = input_ref.base;
    let end = input_ref.end;

    while cur > base {
        let ch = unsafe { *cur as c_int }; // SAFETY: `cur > base` and original code dereferences `cur` under the same conditions.
        if ch != '\n' as c_int && ch != '\r' as c_int {
            break;
        }
        cur = unsafe { cur.offset(-1) }; // SAFETY: guarded by `cur > base`.
    }

    let mut n: c_uint = 0;
    const CONTENT_LEN: usize = 81;
    const CONTENT_MAX: c_uint = 80;

    while n < CONTENT_MAX && cur > base {
        let ch = unsafe { *cur as c_int }; // SAFETY: `cur > base` and original code dereferences `cur` under the same conditions.
        if ch == '\n' as c_int || ch == '\r' as c_int {
            break;
        }
        cur = unsafe { cur.offset(-1) }; // SAFETY: guarded by `cur > base`.
        n = n.wrapping_add(1);
    }

    if n > 0 {
        let ch = unsafe { *cur as c_int }; // SAFETY: same pointer validity assumptions as original code.
        if ch == '\n' as c_int || ch == '\r' as c_int {
            cur = unsafe { cur.offset(1) }; // SAFETY: moving forward after reading current position, matching original behavior.
        } else {
            while cur < input_ref.cur {
                let chb = unsafe { *cur as c_int }; // SAFETY: `cur < input_ref.cur` within the same input buffer as in original code.
                if (chb & 0xc0) != 0x80 {
                    break;
                }
                cur = unsafe { cur.offset(1) }; // SAFETY: guarded by `cur < input_ref.cur`.
            }
        }
    } else {
        while cur < input_ref.cur {
            let chb = unsafe { *cur as c_int }; // SAFETY: `cur < input_ref.cur` within the same input buffer as in original code.
            if (chb & 0xc0) != 0x80 {
                break;
            }
            cur = unsafe { cur.offset(1) }; // SAFETY: guarded by `cur < input_ref.cur`.
        }
    }

    let col = unsafe { input_ref.cur.offset_from(cur) as c_long as c_uint }; // SAFETY: both pointers are within the same allocation as in original code.
    let start = cur;
    n = 0;

    loop {
        let ch = unsafe { *cur as c_int }; // SAFETY: original code dereferences `cur` while scanning the same buffer.
        if ch == 0 || ch == '\n' as c_int || ch == '\r' as c_int {
            break;
        }

        let mut len = unsafe { end.offset_from(cur) as c_long as c_int }; // SAFETY: both pointers are within the same allocation as in original code.
        let c = unsafe { xmlGetUTF8Char(cur as *const c_uchar, &raw mut len) }; // SAFETY: `cur` points into the input buffer and `len` bounds available bytes, matching original call.
        if c < 0 || n.wrapping_add(len as c_uint) > CONTENT_MAX {
            break;
        }
        cur = unsafe { cur.offset(len as isize) }; // SAFETY: `len` was produced for this position by `xmlGetUTF8Char`, matching original behavior.
        n = n.wrapping_add(len as c_uint);
    }

    unsafe {
        memcpy(
            content.as_mut_ptr() as *mut c_void,
            start as *const c_void,
            n as size_t,
        );
    } // SAFETY: `content` has at least `n <= 80` bytes, and `start..start+n` was validated by the scan above as in original code.
    content[n as usize] = 0;

    channel.expect("non-null function pointer")(
        data,
        b"%s\n\0" as *const u8 as *const c_char,
        content.as_mut_ptr(),
    );

    let mut i: c_uint = 0;
    let mut ctnt = content.as_mut_ptr();
    while i < col && i < (CONTENT_LEN as c_uint).wrapping_sub(2) {
        let ch = unsafe { *ctnt as c_int }; // SAFETY: `ctnt` stays within `content` bounds due to loop limit.
        if ch == 0 {
            break;
        }
        if ch != '\t' as c_int {
            unsafe {
                *ctnt = ' ' as i32 as xmlChar;
            } // SAFETY: `ctnt` points within `content` bounds due to loop limit.
        }
        ctnt = unsafe { ctnt.offset(1) }; // SAFETY: bounded by the loop limit to remain within `content`.
        i = i.wrapping_add(1);
    }

    unsafe {
        *ctnt = '^' as i32 as xmlChar;
        *ctnt.offset(1) = 0;
    } // SAFETY: loop ensures `ctnt` is at most `content[79]`, so writing caret and trailing NUL fits in `content`.

    channel.expect("non-null function pointer")(
        data,
        b"%s\n\0" as *const u8 as *const c_char,
        content.as_mut_ptr(),
    );
}

